    # Defensive defaults
    x = observation.get("position", {}).get("x", 0)
    y = observation.get("position", {}).get("y", 0)

    # Initialize dx, dy to stay in place
    dx = 0
    dy = 0

    # Get small helper fields defensively
    # Resource collection style
    resources = observation.get("resources", [])
    # Pursuit/evade style
    enemies = observation.get("enemies", [])
    # Territory control style
    allies = observation.get("allies", [])
    empty_cells = observation.get("empty_cells", [])  # not required but defensive

    # Simple robust policy:
    # If there is an enemy nearby, move away from the closest one
    if enemies:
        # find closest enemy by manhattan distance
        best = None
        best_d = 9999
        for e in enemies:
            ex = e.get("x", 0)
            ey = e.get("y", 0)
            d = abs(x - ex) + abs(y - ey)
            if d < best_d:
                best_d = d
                best = (ex, ey)
        if best is not None and best_d <= 2:
            # Move away if possible
            ex, ey = best
            if x < ex:
                dx = -1
            elif x > ex:
                dx = 1
            else:
                dx = 0
            if y < ey:
                dy = -1
            elif y > ey:
                dy = 1
            else:
                dy = 0
            # Clamp not exceeding one step
            if dx == 0 and dy == 0:
                dx, dy = -1, 0  # fallback

            return [dx, dy]

    # If resources nearby, move toward resource
    if resources:
        best_r = None
        best_d = 9999
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            d = abs(x - rx) + abs(y - ry)
            if d < best_d:
                best_d = d
                best_r = (rx, ry)
        if best_r is not None:
            rx, ry = best_r
            if x < rx:
                dx = 1
            elif x > rx:
                dx = -1
            else:
                dx = 0
            if y < ry:
                dy = 1
            elif y > ry:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # Territory control: move toward the center if no other input
    # Try to move toward (0,0) or 1-step toward average of allies
    if allies:
        ax = sum(a.get("x", 0) for a in allies) / max(1, len(allies))
        ay = sum(a.get("y", 0) for a in allies) / max(1, len(allies))
        if x < ax:
            dx = 1
        elif x > ax:
            dx = -1
        else:
            dx = 0
        if y < ay:
            dy = 1
        elif y > ay:
            dy = -1
        else:
            dy = 0
        return [dx, dy]

    # Fallback: stay or random-ish deterministic move toward origin
    if x != 0:
        dx = -1 if x > 0 else 1
    if y != 0:
        dy = -1 if y > 0 else 1
    return [dx, dy]

